action.query:
SELECT SUM(CASE WHEN IS_CANCELLED THEN 1 ELSE 0 END) * 1.0 / COUNT(*) AS OVERALL_CANCELLATION_RATE, AVG(CASE WHEN IS_DELIVERED THEN DELIVERY_TIME_MIN END) AS OVERALL_AVG_DELIVERY_TIME_DELIVERED
FROM ZOMATO_DLR.CORE.FACT_ORDER
WHERE ORDER_DATE >= '2025-01-01' AND ORDER_DATE < '2026-01-01';
